import sqlite3
import csv
import json

with open('json/superpower.json', 'r') as f:
    superpower_data = json.load(f)

power_id_map = {}
for record in superpower_data['records']:
    power_id_map[record['power_name']] = record['id']

print(f"Super Strength power_id: {power_id_map.get('Super Strength')}")

superheroes = {}
with open('csv/superhero.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        hero_id = int(row['id'])
        height_cm = row['height_cm']
        if height_cm:
            try:
                height_cm = int(height_cm)
            except:
                height_cm = None
        superheroes[hero_id] = {'height_cm': height_cm}

print(f"Total superheroes: {len(superheroes)}")

conn = sqlite3.connect('db/hero_power.db')
cursor = conn.cursor()
cursor.execute('SELECT hero_id, power_id FROM hero_power')
hero_power_map = cursor.fetchall()
conn.close()

print(f"Total hero_power records: {len(hero_power_map)}")

super_strength_id = power_id_map.get('Super Strength')
count = 0
for hero_id, power_id in hero_power_map:
    if power_id == super_strength_id and hero_id in superheroes:
        height = superheroes[hero_id]['height_cm']
        if height and height > 200:
            count += 1

print(f"Superheroes with Super Strength and height > 200cm: {count}")

